#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <zlib.h>

#define N 4096
#define F 18
#define THRESHOLD 2

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    FILE *f = fopen(argv[1], "rb");
    if (!f) return 2;
    fseek(f, 63, SEEK_SET);
    uint8_t hdr[24];
    if (fread(hdr, 1, 24, f) != 24) return 3;
    if (memcmp(hdr, "complzss", 8) != 0) {
        printf("Not complzss\n");
        return 4;
    }
    uint32_t check = (hdr[8]<<24) | (hdr[9]<<16) | (hdr[10]<<8) | hdr[11];
    uint32_t uncomp_len = (hdr[12]<<24) | (hdr[13]<<16) | (hdr[14]<<8) | hdr[15];
    uint32_t comp_len = (hdr[16]<<24) | (hdr[17]<<16) | (hdr[18]<<8) | hdr[19];
    printf("check=0x%08x, uncomp=%u, comp=%u\n", check, uncomp_len, comp_len);

    fseek(f, 63 + 0x180, SEEK_SET);
    uint8_t *src = malloc(comp_len);
    if (fread(src, 1, comp_len, f) != comp_len) {
        printf("Read error\n");
        return 5;
    }
    fclose(f);

    uint8_t *dst = malloc(uncomp_len);
    uint8_t text_buf[N + F - 1];
    memset(text_buf, ' ', N - F);
    int r = N - F;
    int flags = 0;
    uint32_t src_idx = 0;
    uint32_t dst_idx = 0;

    while (src_idx < comp_len && dst_idx < uncomp_len) {
        flags >>= 1;
        if ((flags & 256) == 0) {
            flags = src[src_idx++] | 0xff00;
        }
        if (flags & 1) {
            int c = src[src_idx++];
            dst[dst_idx++] = c;
            text_buf[r] = c;
            r = (r + 1) & (N - 1);
        } else {
            int i = src[src_idx++];
            int j = src[src_idx++];
            i |= (j & 0xf0) << 4;
            j = (j & 0x0f) + THRESHOLD;
            for (int k = 0; k <= j; k++) {
                int c = text_buf[(i + k) & (N - 1)];
                dst[dst_idx++] = c;
                text_buf[r] = c;
                r = (r + 1) & (N - 1);
                if (dst_idx >= uncomp_len) break;
            }
        }
    }
    printf("Decompressed %u bytes (expected %u)\n", dst_idx, uncomp_len);
    uLong adler = adler32(0L, Z_NULL, 0);
    adler = adler32(adler, dst, dst_idx);
    printf("Calculated adler32: 0x%08lx (expected: 0x%08x)\n", adler, check);
    if (adler == check) {
        printf("ADLER32 VERIFICATION SUCCESSFUL!\n");
    } else {
        printf("ADLER32 MISMATCH!\n");
    }

    uint32_t magic = *(uint32_t*)dst;
    printf("Mach-O magic: 0x%08x\n", magic);
    free(src);
    free(dst);
    return 0;
}
EOF
